import re
import urllib.parse
import requests
import json

def task_func(myString, API_KEY):
    url_pattern = r'https?://[^\s]+'
    urls = re.findall(url_pattern, myString)
    domains = set()
    for url in urls:
        try:
            parsed = urllib.parse.urlparse(url)
            host = parsed.netloc.split(':')[0]
            if host:
                domains.add(host)
        except Exception:
            continue
    result = {}
    for domain in domains:
        try:
            api_url = f'https://api.ipapi.com/api/{domain}?access_key={API_KEY}'
            resp = requests.get(api_url, timeout=5)
            if resp.status_code == 200:
                data = resp.json()
                if data.get('status') == 'success' or 'country' in data:
                    result[domain] = data
                else:
                    result[domain] = None
            else:
                result[domain] = None
        except Exception:
            result[domain] = None
    return result

