1. Parse the JSON string into a Python object (dict).
2. Recursively traverse the object to collect all string values.
3. For each string, use a regex to find all substrings matching a typical URL pattern (e.g., http, https, ftp).
4. Count the frequency of each extracted URL using collections.Counter.
5. If top_n is provided, select only the top_n most frequent URLs; otherwise use all.
6. Return a dictionary mapping each URL to its count.

### code
```python
import re
import json
from collections import Counter

def task_func(json_str, top_n=10):
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return {}

    def extract_strings(obj):
        strings = []
        if isinstance(obj, str):
            strings.append(obj)
        elif isinstance(obj, dict):
            for v in obj.values():
                strings.extend(extract_strings(v))
        elif isinstance(obj, list):
            for item in obj:
                strings.extend(extract_strings(item))
        return strings

    url_pattern = r'https?://[^\s"\']+|ftp://[^\s"\']+'
    url_counts = Counter()
    for s in extract_strings(data):
        found_urls = re.findall(url_pattern, s)
        url_counts.update(found_urls)

    if top_n and len(url_counts) > top_n:
        most_common = url_counts.most_common(top_n)
        return dict(most_common)
    else:
        return dict(url_counts)
```

